#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // In-place LU factorization without pivoting (Doolittle-style storage):
    // - U is stored on and above the diagonal
    // - L is stored below the diagonal with implicit unit diagonal
    //
    // For each pivot k:
    //   1) Compute multipliers L(i,k) = A(i,k) / A(k,k) for i > k
    //   2) Update trailing submatrix:
    //        A(i,j) -= L(i,k) * A(k,j),  for i,j > k
    //
    // Parallelization strategy:
    // - The multipliers for a fixed k are independent across i.
    // - After a barrier, each row update of the trailing submatrix is independent.
    // - We use a single parallel region to reduce overhead.
    //
    // Correctness note:
    // - This implementation assumes no zero pivot (no partial pivoting).
    // - Each matrix element is written by at most one thread at a time.

    #pragma omp parallel default(none) shared(A, N)
    {
        for (size_t k = 0; k < N; ++k) {
            const double pivot = A[k * N + k];

            // Compute the k-th column of L below the diagonal.
            #pragma omp for
            for (size_t i = k + 1; i < N; ++i) {
                A[i * N + k] /= pivot;
            }

            // Ensure all multipliers are available before updating the trailing submatrix.
            #pragma omp barrier

            // Update rows of the trailing submatrix.
            #pragma omp for
            for (size_t i = k + 1; i < N; ++i) {
                const double Lik = A[i * N + k];
                const size_t row_i = i * N;
                const size_t row_k = k * N;
                for (size_t j = k + 1; j < N; ++j) {
                    A[row_i + j] -= Lik * A[row_k + j];
                }
            }

            // Implicit barrier at end of omp for ensures next k sees completed updates.
        }
    }
}
